class Assets51(RootModel[Assets52 | Assets53 | Assets54 | Assets55]):
    root: Annotated[Assets52 | Assets53 | Assets54 | Assets55, Field(discriminator='type')]
    def __getattr__(self, name: str) -> Any:
        """Proxy attribute access to the wrapped type."""
